using Microsoft.EntityFrameworkCore;using OAS.Application.Sales.Abstractions;using OAS.Domain.Sales.Entities;using OAS.Infrastructure.Persistence;using OAS.Infrastructure.Persistence.Repositories.Generic;
namespace OAS.Infrastructure.Sales.Persistence.Repositories;
public sealed class OpticalProductionJobRepository(OasDbContext db):EfRepository<OpticalProductionJob,Guid>(db),IOpticalProductionJobRepository{public Task<OpticalProductionJob?> GetAggregateAsync(Guid id,bool tracking,CancellationToken ct=default){IQueryable<OpticalProductionJob>q=Set.Include(x=>x.Materials);if(!tracking)q=q.AsNoTracking();return q.FirstOrDefaultAsync(x=>x.Id==id,ct);}}
